 266→+	req.Header.Set("Accept", "application/json")
 267→+	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
 268→+	req.Header.Set("User-Agent", "entire-cli")
 269→+
 270→+	resp, err := c.httpClient.Do(req) //nolint:gosec // base URL is constrained to Entire API or explicit local dev override
 271→+	if err != nil {
 272→+		return nil, fmt.Errorf("poll device auth: %w", err)
 273→+	}
 274→+	defer resp.Body.Close()
 275→+
 276→+	if resp.StatusCode != http.StatusOK {
 277→+		apiErr, err := readAPIErrorResponse(resp)
 278→+		if err != nil {
 279→+			return nil, fmt.Errorf("poll device auth: %w", err)
 280→+		}
 281→+		return &DeviceAuthPoll{Error: apiErr.Error}, nil
 282→+	}
 283→+
 284→+	var result DeviceAuthPoll
 285→+	if err := decodeJSON(resp.Body, &result); err != nil {
 286→+		return nil, fmt.Errorf("decode device auth poll response: %w", err)
 287→+	}
 288→+
 289→+	return &result, nil
 290→+}
 291→+
 292→+func readAPIErrorResponse(resp *http.Response) (*errorResponse, error) {
 293→+	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
 294→+	if err != nil {
 295→+		return nil, fmt.Errorf("status %d", resp.StatusCode)
 296→+	}
 297→+
 298→+	var apiErr errorResponse
 299→+	if err := json.Unmarshal(body, &apiErr); err == nil && strings.TrimSpace(apiErr.Error) != "" {
 300→+		return &apiErr, nil
 301→+	}
 302→+
 303→+	text := strings.TrimSpace(string(body))
 304→+	if text != "" {
 305→+		return nil, fmt.Errorf("status %d: %s", resp.StatusCode, text)
 306→+	}
 307→+
 308→+	return nil, fmt.Errorf("status %d", resp.StatusCode)
 309→+}
 310→+
 311→+func readAPIError(resp *http.Response, action string) error {
 312→+	apiErr, err := readAPIErrorResponse(resp)
 313→+	if err == nil {
 314→+		return fmt.Errorf("%s: %s", action, apiErr.Error)
 315→+	}
 316→+	return fmt.Errorf("%s: %w", action, err)
 317→+}
 318→+
 319→+func decodeJSON(r io.Reader, dest any) error {
 320→+	return decodeJSONWithOptions(r, dest, false)
 321→+}
 322→+
 323→+func decodeJSONStrict(r io.Reader, dest any) error {
 324→+	return decodeJSONWithOptions(r, dest, true)
 325→+}
 326→+
 327→+func decodeJSONWithOptions(r io.Reader, dest any, strict bool) error {
 328→+	body, err := io.ReadAll(io.LimitReader(r, maxResponseBytes))
 329→+	if err != nil {
 330→+		return fmt.Errorf("read JSON response: %w", err)
 331→+	}
 332→+
 333→+	dec := json.NewDecoder(bytes.NewReader(body))
 334→+	if strict {
 335→+		dec.DisallowUnknownFields()
 336→+	}
 337→+	if err := dec.Decode(dest); err != nil {
 338→+		return fmt.Errorf("decode JSON response: %w", err)
 339→+	}
 340→+
 341→+	return nil
 342→+}
