 442→+func (s *Store) SaveToken(baseURL, token string) error {
 443→+	state, err := s.Load()
 444→+	if err != nil {
 445→+		return err
 446→+	}
 447→+
 448→+	if state.Tokens == nil {
 449→+		state.Tokens = make(map[string]Token)
 450→+	}
 451→+
 452→+	state.Tokens[baseURL] = Token{
 453→+		Value:     token,
 454→+		CreatedAt: time.Now().UTC().Format(time.RFC3339),
 455→+	}
 456→+
 457→+	return s.save(state)
 458→+}
 459→+
 460→+func (s *Store) Load() (*File, error) {
 461→+	data, err := os.ReadFile(s.filePath)
 462→+	if err != nil {
 463→+		if os.IsNotExist(err) {
 464→+			return &File{}, nil
 465→+		}
 466→+		return nil, fmt.Errorf("read auth file: %w", err)
 467→+	}
 468→+
 469→+	var state File
 470→+	if err := json.Unmarshal(data, &state); err != nil {
 471→+		return nil, fmt.Errorf("parse auth file: %w", err)
 472→+	}
 473→+
 474→+	return &state, nil
 475→+}
