 477→+func defaultFilePath() (string, error) {
 478→+	home, err := os.UserHomeDir()
 479→+	if err != nil {
 480→+		return "", fmt.Errorf("get home directory: %w", err)
 481→+	}
 482→+
 483→+	return filepath.Join(home, ".config", "entire", authFileName), nil
 484→+}
 485→+
 486→+func (s *Store) save(state *File) error {
 487→+	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
 488→+	if err != nil {
 489→+		return fmt.Errorf("marshal auth file: %w", err)
 490→+	}
 491→+
 492→+	dir := filepath.Dir(s.filePath)
 493→+	if err := os.MkdirAll(dir, 0o700); err != nil {
 494→+		return fmt.Errorf("create auth directory: %w", err)
 495→+	}
 496→+
 497→+	tmpFile, err := os.CreateTemp(dir, ".auth_tmp_")
 498→+	if err != nil {
 499→+		return fmt.Errorf("create temp auth file: %w", err)
 500→+	}
 501→+	defer os.Remove(tmpFile.Name())
 502→+
 503→+	if err := tmpFile.Chmod(0o600); err != nil {
 504→+		_ = tmpFile.Close()
 505→+		return fmt.Errorf("set temp auth permissions: %w", err)
 506→+	}
 507→+
 508→+	if _, err := tmpFile.Write(data); err != nil {
 509→+		_ = tmpFile.Close()
 510→+		return fmt.Errorf("write temp auth file: %w", err)
 511→+	}
 512→+
 513→+	if err := tmpFile.Close(); err != nil {
 514→+		return fmt.Errorf("close temp auth file: %w", err)
 515→+	}
 516→+
 517→+	if err := os.Rename(tmpFile.Name(), s.filePath); err != nil { //nolint:gosec // destination path is internally constructed or test-controlled
 518→+		return fmt.Errorf("rename auth file: %w", err)
 519→+	}
 520→+
 521→+	return nil
 522→+}
 523→+
 524→+func LookupToken(state *File) string {
 525→+	if state == nil || state.Tokens == nil {
 526→+		return ""
 527→+	}
 528→+
 529→+	entry, ok := state.Tokens[apiurl.BaseURL()]
 530→+	if !ok {
 531→+		return ""
 532→+	}
 533→+
 534→+	return entry.Value
 535→+}
