1034→+func waitForApproval(ctx context.Context, client *auth.Client, deviceCode string, expiresIn, interval int) (string, error) {
1035→+	deadline := time.Now().Add(time.Duration(expiresIn) * time.Second)
1036→+	pollInterval := time.Duration(interval) * time.Second
1037→+	if pollInterval <= 0 {
1038→+		pollInterval = fallbackDeviceAuthPollInterval
1039→+	}
1040→+
1041→+	for {
1042→+		if time.Now().After(deadline) {
1043→+			return "", errors.New("device authorization expired")
1044→+		}
1045→+
1046→+		result, err := client.PollDeviceAuth(ctx, deviceCode)
1047→+		if err != nil {
1048→+			return "", fmt.Errorf("poll approval status: %w", err)
1049→+		}
1050→+
1051→+		switch result.Error {
1052→+		case "", "authorization_pending":
1053→+			// continue below
1054→+		case "slow_down":
1055→+			pollInterval += slowDownBackoff
1056→+		case "access_denied":
1057→+			return "", errors.New("device authorization denied")
1058→+		case "expired_token":
1059→+			return "", errors.New("device authorization expired")
1060→+		default:
1061→+			return "", fmt.Errorf("device authorization failed: %s", result.Error)
1062→+		}
1063→+
1064→+		if result.Error == "" {
1065→+			if result.AccessToken == "" {
1066→+				return "", errors.New("device authorization completed without a token")
1067→+			}
1068→+			return result.AccessToken, nil
1069→+		}
1070→+
1071→+		select {
1072→+		case <-ctx.Done():
1073→+			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
1074→+		case <-time.After(pollInterval):
1075→+		}
1076→+	}
1077→+}
