 90→func (s *Store) save(state *File) error {
 91→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
 92→	if err != nil {
 93→		return fmt.Errorf("marshal auth file: %w", err)
 94→	}
 95→
 96→	dir := filepath.Dir(s.filePath)
 97→	if err := os.MkdirAll(dir, 0o700); err != nil {
 98→		return fmt.Errorf("create auth directory: %w", err)
 99→	}
100→
101→	tmpFile, err := os.CreateTemp(dir, ".auth_tmp_")
102→	if err != nil {
103→		return fmt.Errorf("create temp auth file: %w", err)
104→	}
105→	defer os.Remove(tmpFile.Name())
106→
107→	if err := tmpFile.Chmod(0o600); err != nil {
108→		_ = tmpFile.Close()
109→		return fmt.Errorf("set temp auth permissions: %w", err)
110→	}
111→
112→	if _, err := tmpFile.Write(data); err != nil {
113→		_ = tmpFile.Close()
114→		return fmt.Errorf("write temp auth file: %w", err)
115→	}
116→
117→	if err := tmpFile.Close(); err != nil {
118→		return fmt.Errorf("close temp auth file: %w", err)
119→	}
120→
121→	if err := os.Rename(tmpFile.Name(), s.filePath); err != nil { //nolint:gosec // destination path is internally constructed or test-controlled
122→		return fmt.Errorf("rename auth file: %w", err)
123→	}
124→
125→	return nil
126→}
