 97→func (c *Client) PollDeviceAuth(ctx context.Context, deviceCode string) (*DeviceAuthPoll, error) {
 98→	endpoint, err := apiurl.ResolveURLFromBase(c.baseURL, "/oauth/token")
 99→	if err != nil {
100→		return nil, fmt.Errorf("resolve device auth poll URL: %w", err)
101→	}
102→
103→	body := url.Values{}
104→	body.Set("grant_type", "urn:ietf:params:oauth:grant-type:device_code")
105→	body.Set("client_id", "entire-cli")
106→	body.Set("device_code", deviceCode)
107→
108→	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, strings.NewReader(body.Encode()))
109→	if err != nil {
110→		return nil, fmt.Errorf("create device auth poll request: %w", err)
111→	}
112→
113→	req.Header.Set("Accept", "application/json")
114→	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
115→	req.Header.Set("User-Agent", "entire-cli")
116→
117→	resp, err := c.httpClient.Do(req) //nolint:gosec // base URL is constrained to Entire API or explicit local dev override
118→	if err != nil {
119→		return nil, fmt.Errorf("poll device auth: %w", err)
120→	}
121→	defer resp.Body.Close()
122→
123→	if resp.StatusCode != http.StatusOK {
124→		apiErr, err := readAPIErrorResponse(resp)
125→		if err != nil {
126→			return nil, fmt.Errorf("poll device auth: %w", err)
127→		}
128→		return &DeviceAuthPoll{Error: apiErr.Error}, nil
129→	}
130→
131→	var result DeviceAuthPoll
132→	if err := decodeJSON(resp.Body, &result); err != nil {
133→		return nil, fmt.Errorf("decode device auth poll response: %w", err)
134→	}
135→
136→	return &result, nil
137→}
