139→func readAPIErrorResponse(resp *http.Response) (*errorResponse, error) {
140→	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
141→	if err != nil {
142→		return nil, fmt.Errorf("status %d", resp.StatusCode)
143→	}
144→
145→	var apiErr errorResponse
146→	if err := json.Unmarshal(body, &apiErr); err == nil && strings.TrimSpace(apiErr.Error) != "" {
147→		return &apiErr, nil
148→	}
149→
150→	text := strings.TrimSpace(string(body))
151→	if text != "" {
152→		return nil, fmt.Errorf("status %d: %s", resp.StatusCode, text)
153→	}
154→
155→	return nil, fmt.Errorf("status %d", resp.StatusCode)
156→}
157→
158→func readAPIError(resp *http.Response, action string) error {
159→	apiErr, err := readAPIErrorResponse(resp)
160→	if err == nil {
161→		return fmt.Errorf("%s: %s", action, apiErr.Error)
162→	}
163→	return fmt.Errorf("%s: %w", action, err)
164→}
165→
166→func decodeJSON(r io.Reader, dest any) error {
167→	return decodeJSONWithOptions(r, dest, false)
168→}
169→
170→func decodeJSONStrict(r io.Reader, dest any) error {
171→	return decodeJSONWithOptions(r, dest, true)
172→}
173→
174→func decodeJSONWithOptions(r io.Reader, dest any, strict bool) error {
175→	body, err := io.ReadAll(io.LimitReader(r, maxResponseBytes))
176→	if err != nil {
177→		return fmt.Errorf("read JSON response: %w", err)
178→	}
179→
180→	dec := json.NewDecoder(bytes.NewReader(body))
181→	if strict {
182→		dec.DisallowUnknownFields()
183→	}
184→	if err := dec.Decode(dest); err != nil {
185→		return fmt.Errorf("decode JSON response: %w", err)
186→	}
187→
188→	return nil
189→}
