 16→
 17→const fallbackDeviceAuthPollInterval = time.Second
 18→const slowDownBackoff = 5 * time.Second
 19→const maxPollInterval = 30 * time.Second
 20→const maxExpiresIn = 15 * time.Minute
 21→
 22→var browserOpener = openBrowser
 23→
 24→func newLoginCmd() *cobra.Command {
 25→	var printBrowserURL bool
 26→
 27→	cmd := &cobra.Command{
 28→		Use:   "login",
 29→		Short: "Log in to Entire",
 30→		RunE: func(cmd *cobra.Command, _ []string) error {
 31→			return runLogin(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), printBrowserURL)
 32→		},
 33→	}
 34→
 35→	cmd.Flags().BoolVar(&printBrowserURL, "print-browser-url", false, "Print the approval URL instead of opening a browser")
 36→
 37→	return cmd
 38→}
