 40→func runLogin(ctx context.Context, outW, errW io.Writer, printBrowserURL bool) error {
 41→	client := auth.NewClient(nil)
 42→
 43→	start, err := client.StartDeviceAuth(ctx)
 44→	if err != nil {
 45→		return fmt.Errorf("start login: %w", err)
 46→	}
 47→
 48→	fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)
 49→	approvalURL := start.VerificationURIComplete
 50→	if approvalURL == "" {
 51→		approvalURL = start.VerificationURI
 52→	}
 53→
 54→	fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)
 55→
 56→	if printBrowserURL {
 57→		fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
 58→	} else {
 59→		if err := browserOpener(ctx, approvalURL); err != nil {
 60→			fmt.Fprintf(errW, "Warning: failed to open browser automatically: %v\n", err)
 61→			fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
 62→		} else {
 63→			fmt.Fprintln(outW, "Opened your browser for approval.")
 64→		}
 65→	}
 66→
 67→	fmt.Fprintln(outW, "Waiting for approval...")
 68→
 69→	token, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, start.Interval)
 70→	if err != nil {
 71→		return fmt.Errorf("complete login: %w", err)
 72→	}
 73→
 74→	store, err := auth.NewStore()
 75→	if err != nil {
 76→		return fmt.Errorf("create auth store: %w", err)
 77→	}
 78→
 79→	if err := store.SaveToken(client.BaseURL(), token); err != nil {
 80→		return fmt.Errorf("save auth token: %w", err)
 81→	}
 82→
 83→	fmt.Fprintf(outW, "Login complete. Saved token to %s\n", store.FilePath())
 84→	return nil
 85→}
