 87→func waitForApproval(ctx context.Context, client *auth.Client, deviceCode string, expiresIn, interval int) (string, error) {
 88→	expiry := time.Duration(expiresIn) * time.Second
 89→	if expiry <= 0 || expiry > maxExpiresIn {
 90→		expiry = maxExpiresIn
 91→	}
 92→	deadline := time.Now().Add(expiry)
 93→	pollInterval := time.Duration(interval) * time.Second
 94→	if pollInterval <= 0 {
 95→		pollInterval = fallbackDeviceAuthPollInterval
 96→	}
 97→
 98→	for {
 99→		if time.Now().After(deadline) {
100→			return "", errors.New("device authorization expired")
101→		}
102→
103→		result, err := client.PollDeviceAuth(ctx, deviceCode)
104→		if err != nil {
105→			return "", fmt.Errorf("poll approval status: %w", err)
106→		}
107→
108→		switch result.Error {
109→		case "", "authorization_pending":
110→			// continue below
111→		case "slow_down":
112→			pollInterval += slowDownBackoff
113→			if pollInterval > maxPollInterval {
114→				pollInterval = maxPollInterval
115→			}
116→		case "access_denied":
117→			return "", errors.New("device authorization denied")
118→		case "expired_token":
119→			return "", errors.New("device authorization expired")
120→		default:
121→			return "", fmt.Errorf("device authorization failed: %s", result.Error)
122→		}
123→
124→		if result.Error == "" {
125→			if result.AccessToken == "" {
126→				return "", errors.New("device authorization completed without a token")
127→			}
128→			return result.AccessToken, nil
129→		}
130→
131→		select {
132→		case <-ctx.Done():
133→			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
134→		case <-time.After(pollInterval):
135→		}
136→	}
137→}
